<?php use yii\helpers\{Html,Url};use yii\widgets\ActiveForm;$this->title='Sign in';?><main class="loginbox"><section class="loginbrand"><img src="<?=Url::to('@web/assets/sppu/dti-logo.png')?>"><p>Department of Trade and Industry • Caraga</p><h1>Supply and Property<br>Tracking System</h1><span>Yii2 Edition</span></section><section class="logincard"><h2>Welcome back</h2><p>Sign in to manage property and supply records.</p><?php $f=ActiveForm::begin();?><?=$f->field($model,'email')->input('email',['autocomplete'=>'username'])?><?=$f->field($model,'password')->passwordInput(['autocomplete'=>'current-password'])?><?=Html::submitButton('Sign in',['class'=>'btn primary'])?><?php ActiveForm::end();?><?=Html::a('Register new user',['register'],['class'=>'btn','style'=>'display:block;text-align:center;margin-top:14px'])?></section></main>
